// Adapt the official r158 ESM loader to this game's existing global THREE instance.
const fs=require('node:fs'), path=require('node:path');
const read=n=>fs.readFileSync(path.join(__dirname,n),'utf8');
const globals=s=>s.replace(/import\s*\{([\s\S]*?)\}\s*from 'three';/, 'const {$1} = window.THREE;');
const utils=globals(read('BufferGeometryUtils.source.js')).replace(/export\s+(?=function)/g,'').replace(/export\s*\{[\s\S]*?\};\s*$/, 'return {toTrianglesDrawMode};');
const loader=globals(read('GLTFLoader.source.js'))
  .replace("import { toTrianglesDrawMode } from '../utils/BufferGeometryUtils.js';",`const {toTrianglesDrawMode} = (()=>{\n${utils}\n})();`)
  .replace(/export\s*\{\s*GLTFLoader\s*\};/, 'window.BeltRunnerGLTFLoader = GLTFLoader;');
fs.writeFileSync(path.join(__dirname,'GLTFLoader.js'),'// Three.js r158, MIT license; see LICENSE. Generated by build-loader.cjs.\n(()=>{\n'+loader+'\n})();\n');
require('../../assets/cargo_carrier_v2/build-game-assets.cjs');
